const escapeHtml=(value:string)=>value.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');

function sanitizeHtml(html:string){
  const template=window.document.createElement('template'); template.innerHTML=html;
  template.content.querySelectorAll('script,iframe,object,embed,form,style,link,meta').forEach(node=>node.remove());
  template.content.querySelectorAll('*').forEach(node=>[...node.attributes].forEach(attr=>{
    const name=attr.name.toLowerCase(),value=attr.value.trim().toLowerCase();
    const safeEmbeddedImage=name==='src'&&/^data:image\/(?:png|jpeg|gif|webp);base64,/i.test(attr.value.trim());if(name.startsWith('on')||name==='srcdoc'||((name==='href'||name==='src')&&(value.startsWith('javascript:')||(value.startsWith('data:')&&!safeEmbeddedImage)))) node.removeAttribute(attr.name);
  }));
  return template.innerHTML;
}

/** Apply safe stylesheet rules to imported HTML before removing its stylesheet.
 * Keeps document appearance when importing standalone HTML exported by Docs/Word.
 */
function prepareImportedHtml(source:string):{html:string;layout:Partial<EditorLayoutSettings>}{
  const parsed=new DOMParser().parseFromString(source,'text/html');
  const layout:Partial<EditorLayoutSettings>={};
  const css=[...parsed.querySelectorAll('style')].map(node=>node.textContent||'').join('\n');
  const allCss=css+'\n'+[...parsed.querySelectorAll('[style]')].map(node=>node.getAttribute('style')||'').join('\n');
  const page=allCss.match(/@page\s*[^\{]*\{([^}]*)\}/i)?.[1]||'';
  const size=page.match(/size\s*:\s*(A4|Letter)(?:\s+(portrait|landscape))?/i);
  if(size){layout.pageSize=size[1].toLowerCase()==='letter'?'Letter':'A4';layout.orientation=(size[2]?.toLowerCase()==='landscape'?'landscape':'portrait')}
  const margin=page.match(/margin\s*:\s*(\d+(?:\.\d+)?)\s*mm/i);
  if(margin){const n=Math.round(Number(margin[1]));if([10,15,20,25,30].includes(n))layout.margin=n}
  const rules=[...css.matchAll(/([^{}]+)\{([^{}]+)\}/g)];
  for(const [,selectorText,declarations] of rules){
    if(selectorText.trim().startsWith('@'))continue;
    const safeDeclarations=declarations.split(';').map(part=>part.trim()).filter(part=>{
      const idx=part.indexOf(':');if(idx<1)return false;
      const prop=part.slice(0,idx).trim().toLowerCase(),val=part.slice(idx+1).trim();
      return /^(color|background|background-color|font-family|font-size|font-weight|font-style|font-variant|text-align|text-decoration|text-transform|line-height|letter-spacing|text-indent|margin(?:-top|-right|-bottom|-left)?|padding(?:-top|-right|-bottom|-left)?|border(?:-(?:top|right|bottom|left))?(?:-(?:color|style|width))?|border-collapse|border-spacing|table-layout|width|min-width|max-width|height|min-height|max-height|vertical-align|white-space|word-break|overflow-wrap|list-style-type)$/.test(prop)&&!/(url\s*\(|expression\s*\(|javascript:|@import)/i.test(val);
    }).join(';');
    if(!safeDeclarations)continue;
    for(const selector of selectorText.split(',')){
      const trimmed=selector.trim();
      if(!trimmed||/[>+~:]|\[|\]/.test(trimmed)||trimmed.length>100)continue;
      try{parsed.querySelectorAll(trimmed).forEach(element=>{
        const existing=(element.getAttribute('style')||'').trim();
        element.setAttribute('style',[existing,safeDeclarations].filter(Boolean).join(';'));
      })}catch{/* Ignore unsupported selectors in imported documents. */}
    }
  }
  const pageBox=allCss.match(/@top-(left|center|right)\s*\{[^}]*content\s*:\s*["']([^"']*)["']/i);
  if(pageBox){layout.headerAlign=pageBox[1].toLowerCase() as 'left'|'center'|'right';layout.headerText=pageBox[2]}
  const footerBoxes=[...allCss.matchAll(/@bottom-(left|center|right)\s*\{([^}]*)\}/gi)];
  const footerBox=footerBoxes.find(match=>!/counter\s*\(\s*page\s*\)/i.test(match[2])&&/content\s*:\s*["'][^"']*["']/i.test(match[2]));
  if(footerBox){const text=footerBox[2].match(/content\s*:\s*["']([^"']*)["']/i);if(text){layout.footerAlign=footerBox[1].toLowerCase() as 'left'|'center'|'right';layout.footerText=text[1]}}
  parsed.querySelectorAll('style,link,meta,script,iframe,object,embed,form').forEach(node=>node.remove());
  const body=parsed.body.innerHTML||source;
  return {html:sanitizeHtml(body),layout};
}
