type PageSize='A3'|'A4'|'A5'|'B5'|'Letter'|'Legal'|'Executive'|'Tabloid';
const PAGE_MM:Record<PageSize,[number,number]>={A3:[297,420],A4:[210,297],A5:[148,210],B5:[176,250],Letter:[215.9,279.4],Legal:[215.9,355.6],Executive:[184.15,266.7],Tabloid:[279.4,431.8]};
function detectPageSize(widthPx:number,heightPx:number):{pageSize:PageSize;orientation:Orientation}{const w=widthPx*25.4/96,h=heightPx*25.4/96;let best:{pageSize:PageSize;orientation:Orientation;delta:number}={pageSize:'A4',orientation:'portrait',delta:Infinity};for(const [name,dims] of Object.entries(PAGE_MM) as [PageSize,[number,number]][]){for(const orientation of ['portrait','landscape'] as Orientation[]){const [pw,ph]=orientation==='portrait'?dims:[dims[1],dims[0]];const delta=Math.abs(w-pw)+Math.abs(h-ph);if(delta<best.delta)best={pageSize:name,orientation,delta}}}return {pageSize:best.pageSize,orientation:best.orientation}}
type Orientation='portrait'|'landscape';
